<template>
  <div class="generated-view">
    <p v-if="!embedded && showBackLink" class="back-link back-link-top">
      <button type="button" class="site-back-control" @click="goBack()">
        <span class="back-link-arrow" aria-hidden="true">←</span>
        <span>Back to {{ originLabel }}</span>
      </button>
    </p>
    <header v-if="!fatalError && (!shareId || !sourcesLoading)" class="view-header">
      <div class="view-meta-row">
        <div class="view-meta-stack">
          <p class="view-ai-note">
            <span class="view-ai-badge"><span aria-hidden="true">✦</span> Created with AI</span>
            <span v-if="!sourcesLoading" class="view-meta-unit">using {{ sourceCount }} {{ sourceCount === 1 ? 'source' : 'sources' }} from Henry&rsquo;s site</span>
            <span v-else class="view-meta-unit">using Henry&rsquo;s original site material</span>
          </p>
          <ViewTranslationControl
            v-if="translationAvailable"
            :loading="translationLoading"
            :visible="translationVisible"
            :loaded="hasTranslations"
            :error="translationError"
            @toggle="toggleTranslation"
          />
        </div>
      </div>
      <h1 ref="viewTitle" tabindex="-1" data-scroll-reveal>{{ view.title }}</h1>
      <transition name="translation-reveal">
        <p v-if="translationVisible && translationFor('title')" class="view-translation-text view-title-translation" :lang="translationLang">
          {{ translationFor('title') }}
        </p>
      </transition>
      <div v-if="displayQuestion" class="view-question-group" data-scroll-reveal>
        <p class="view-question">&ldquo;{{ displayQuestion }}&rdquo;</p>
        <transition name="translation-reveal">
          <p v-if="translationVisible && translationFor('question')" class="view-translation-text view-question-translation" :lang="translationLang">
            &ldquo;{{ translationFor('question') }}&rdquo;
          </p>
        </transition>
        <p v-if="formattedCreatedAt" class="view-question-date">
          A visitor&rsquo;s perspective from <time :datetime="createdAtIso">{{ formattedCreatedAt }}</time>
        </p>
      </div>
      <p v-if="view.dek" class="view-dek" data-scroll-reveal>{{ view.dek }}</p>
      <transition name="translation-reveal">
        <p v-if="translationVisible && translationFor('summary')" class="view-translation-text view-dek-translation" :lang="translationLang">
          {{ translationFor('summary') }}
        </p>
      </transition>
      <ViewSummaryAudio v-if="view.dek" :key="view.dek" :share-id="shareId" :audio-src="view.audio?.src || ''" />
      <figure v-if="view.illustration && view.illustration.src" class="view-illustration" data-scroll-reveal>
        <img
          :src="view.illustration.src"
          :alt="view.illustration.alt || ''"
          loading="eager"
          decoding="async"
        >
      </figure>
    </header>

    <transition name="view-fade">
      <aside v-if="sourceNotice" class="view-source-notice" role="status">
        <div>
          <span>This source has changed</span>
          <p>{{ sourceNotice }}</p>
        </div>
        <button type="button" aria-label="Dismiss source notice" @click="sourceNotice = ''">&times;</button>
      </aside>
    </transition>

    <div v-if="sourcesLoading" class="view-loading" role="status" aria-live="polite">
      <MorphingInfinity class="view-loading-mark" />
      <span>Preparing this <AiViewTerm />…</span>
    </div>

    <section v-else-if="fatalError" class="view-fatal" role="alert">
      <p class="view-kicker"><span aria-hidden="true">✦</span> <AiViewTerm /> unavailable</p>
      <h1>This <AiViewTerm /> could not be opened</h1>
      <p>{{ fatalError }}</p>
      <button v-if="!embedded" type="button" class="site-back-control" @click="goBack()"><span class="back-link-arrow" aria-hidden="true">←</span><span>Back to {{ originLabel }}</span></button>
    </section>

    <article v-else class="view-sections" ref="sections">
      <transition name="view-fade" mode="out-in">
        <div :key="revision" class="view-state">
          <section
            v-for="(section, sectionIndex) in view.sections"
            :key="`${revision}-${sectionIndex}`"
            class="view-section"
          >
            <template v-if="section.heading">
              <h2 class="view-section-heading">{{ section.heading }}</h2>
              <transition name="translation-reveal">
                <p v-if="translationVisible && translationFor(`section.${sectionIndex}`)" class="view-translation-text view-section-translation" :lang="translationLang">
                  {{ translationFor(`section.${sectionIndex}`) }}
                </p>
              </transition>
            </template>
            <div
              v-for="(block, blockIndex) in section.blocks"
              :key="`${revision}-${sectionIndex}-${blockIndex}`"
              class="view-block"
              :class="blockClass(block)"
              :data-source-id="block.kind === 'source' ? block.source_id : null"
            >
              <ViewBridge
                v-if="block.kind === 'bridge'"
                :bridge="block"
                :translated-text="translationVisible ? translationFor(`bridge.${sectionIndex}.${blockIndex}`) : ''"
                :translation-lang="translationLang"
              />
              <ViewSourceBlock
                v-else
                :block="block"
                :source="sourceFor(block.source_id)"
                :current-source="currentSourceFor(block.source_id)"
                @open-source="openSource"
                @source-error="markSourceError"
              />
            </div>
          </section>
        </div>
      </transition>
    </article>

    <p v-if="viewError && !fatalError" class="view-error" role="status">
      Some media could not be loaded. The rest of the page is still available.
    </p>

    <footer v-if="!sourcesLoading && !fatalError" class="view-endnote">
      <section class="view-sharing" aria-labelledby="view-sharing-title" :aria-busy="shareLoading || publishing">
        <div class="view-sharing-heading">
          <div>
            <p class="view-sharing-kicker">
              <span aria-hidden="true">✦</span>
              <template v-if="sharing.status === 'saving'">Saving this <AiViewTerm /></template>
              <template v-else-if="sharing.status === 'public'">Shared publicly</template>
              <template v-else-if="sharing.status === 'unsaved'">Link not saved</template>
              <template v-else>Link-only <AiViewTerm /></template>
            </p>
            <h2 id="view-sharing-title">{{ sharing.title }}</h2>
          </div>
          <router-link class="view-browse-link" to="/views">Browse Shared <AiViewTerm plural /> <ArrowUpRightIcon class="view-browse-arrow" /></router-link>
        </div>
        <p v-if="sharing.status === 'saving'" class="view-sharing-copy">Saving a permanent link to this <AiViewTerm />. It will stay out of Shared <AiViewTerm plural /> unless you choose to publish it.</p>
        <p v-else-if="sharing.status === 'unsaved'" class="view-sharing-copy">You can read this <AiViewTerm /> here. Its permanent link has not been saved yet.</p>
        <p v-else-if="sharing.status === 'public'" class="view-sharing-copy">Visitors can find this <AiViewTerm /> in Shared <AiViewTerm plural />. Anyone can open or share its permanent link.</p>
        <p v-else-if="!shareOwner" class="view-sharing-copy">Anyone with this link can open this <AiViewTerm />. It is not listed in Shared <AiViewTerm plural />. Only its creator can publish it.</p>
        <p v-else class="view-sharing-copy">Anyone with the link can open this <AiViewTerm />. It is not listed in Shared <AiViewTerm plural /> until you choose to publish it.</p>
        <div class="view-sharing-actions">
          <button v-if="shareId || shareLoading" type="button" :disabled="!sharing.canCopy" @click="copyShareLink">
            <span>{{ copied ? 'Link copied' : 'Copy permanent link' }}</span>
            <span v-if="copied" aria-hidden="true">✓</span>
            <ArrowUpRightIcon v-else />
          </button>
          <button
            v-if="sharing.showPublish"
            type="button"
            :disabled="!sharing.canPublish"
            @click="openPublishConfirmation"
          >
            <span>Share this <AiViewTerm /> publicly</span>
            <span aria-hidden="true">＋</span>
          </button>
          <button v-if="sharing.canRetry" type="button" @click="ensurePermanentLink()">
            <span>Retry saving link</span>
            <ArrowUpRightIcon />
          </button>
        </div>
        <transition name="view-confirm">
          <section
            v-if="publishConfirmOpen && sharing.showPublish"
            ref="publishConfirm"
            class="view-publish-confirm"
            role="dialog"
            aria-labelledby="view-publish-confirm-title"
            tabindex="-1"
            @keydown.esc.stop="closePublishConfirmation"
          >
            <p id="view-publish-confirm-title" class="view-publish-confirm-title">Share this <AiViewTerm /> publicly?</p>
            <p>This <AiViewTerm />, its angle, and its permanent link will appear in Shared <AiViewTerm plural />. If you later want it removed, email <a href="mailto:whenry6688@gmail.com">Henry</a>.</p>
            <div class="view-publish-confirm-actions">
              <button type="button" class="view-publish-cancel" :disabled="publishing" @click="closePublishConfirmation">Keep link-only</button>
              <button type="button" class="view-publish-commit" :disabled="publishing" @click="publishView">
                {{ publishing ? 'Sharing…' : 'Share publicly' }}
              </button>
            </div>
          </section>
        </transition>
        <p v-if="shareNotice" class="view-sharing-notice" role="status">{{ shareNotice }}</p>
        <details v-if="sharing.status === 'public'" class="view-sharing-details">
          <summary>About this shared <AiViewTerm /></summary>
          <p>This <AiViewTerm /> and its angle are public. To request removal from Shared <AiViewTerm plural />, email <a href="mailto:whenry6688@gmail.com">Henry</a>.</p>
        </details>
        <details v-else-if="shareOwner" class="view-sharing-details">
          <summary>About public sharing</summary>
          <p>This <AiViewTerm /> and the angle shown here will be shared. Your other Ask activity stays private. Fresh angles are easier for visitors to discover. Shared <AiViewTerm plural /> stay public. For removal, email <a href="mailto:whenry6688@gmail.com">Henry</a>.</p>
        </details>
      </section>
      <div class="view-disclaimer">
        <span aria-hidden="true">✦</span>
        <p><strong>AI-generated</strong> This page may contain errors or omissions.</p>
      </div>
      <details v-if="translationVisible" class="view-translation-disclaimer">
        <summary>About this translation</summary>
        <p>THIS SERVICE MAY CONTAIN TRANSLATIONS POWERED BY GOOGLE. GOOGLE DISCLAIMS ALL WARRANTIES RELATED TO THE TRANSLATIONS, EXPRESS OR IMPLIED, INCLUDING ANY WARRANTIES OF ACCURACY, RELIABILITY, AND ANY IMPLIED WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT.</p>
      </details>
      <section v-if="viewSources.length" class="view-citations" aria-labelledby="view-citations-title">
        <div class="view-citations-heading">
          <h2 id="view-citations-title">Citations</h2>
          <p>Original material used to compose this <AiViewTerm /></p>
        </div>
        <ol>
          <li v-for="(source, index) in viewSources" :key="source.source_id">
            <button type="button" @click="openSource(source)">
              <span class="view-citation-number">{{ String(index + 1).padStart(2, '0') }}</span>
              <span class="view-citation-copy">
                <span>{{ sourcePageLabel(source) }}</span>
                <strong>{{ citationTitle(source) }}</strong>
              </span>
              <ArrowUpRightIcon class="view-citation-arrow" />
            </button>
          </li>
        </ol>
      </section>
    </footer>
  </div>
</template>

<script>
import scrollRevealMixin from '../mixins/scrollRevealMixin';
import {
  consumePendingViewReturnScroll,
  getViewOriginRoute,
  loadAskSession,
  setAskShare,
} from '../utils/askSession';
import { createViewCatalog } from '../utils/viewCatalog.js';
import ViewBridge from './view/ViewBridge.vue';
import ViewSummaryAudio from './view/ViewSummaryAudio.vue';
import ViewTranslationControl from './view/ViewTranslationControl.vue';
import ViewSourceBlock from './view/ViewSourceBlock.vue';
import AiViewTerm from './ui/AiViewTerm.vue';
import MorphingInfinity from './ui/MorphingInfinity.vue';
import { logEvent } from '../utils/askTelemetry';
import { validateViewState } from '../utils/viewValidation';
import {
  createSharedView,
  getSharedView,
  getViewTranslationStatus,
  publishSharedView,
  translateViewToEnglish,
} from '../utils/viewShareSite';
import { sourceFingerprint } from '../utils/viewSnapshotCompare';
import { sourceDisplayTitle } from '../utils/askRetrieval';
import { sourcePageLabel, viewSourceTarget } from '../utils/viewSourceTarget';
import { viewSharingState } from '../utils/viewSharingState';

const ROUTE_LABELS = {
  '/about': 'About',
  '/education': 'Education',
  '/experience': 'Experience',
  '/research': 'Research',
  '/projects': 'Builds',
  '/fragments': 'Fragments',
  '/travels': 'Travels',
  '/views': 'Views',
  '/cv': 'CV',
  '/aipersonalarchive': 'Search story',
  '/playbook': 'Playbook',
  '/lexaday': 'Lexaday',
  '/dealtracker': 'Dealtracker',
  '/scrollytelling': 'Scrollytelling',
  '/early': 'Early builds',
  '/ragflow-pipeline': 'Ragflow pipeline',
  '/home': 'Home',
  '/': 'Home',
};

export default {
  name: 'GeneratedViewPage',
  components: { AiViewTerm, MorphingInfinity, ViewBridge, ViewSourceBlock, ViewSummaryAudio, ViewTranslationControl },
  mixins: [scrollRevealMixin],
  data() {
    return {
      view: {
        schema_version: 1,
        question: '',
        lens: '',
        title: 'Composed view',
        dek: '',
        sections: [],
      },
      revision: 0,
      session: null,
      sourcesById: new Map(),
      currentSourcesById: new Map(),
      viewError: false,
      fatalError: '',
      sourcesLoading: true,
      shareId: '',
      shareOwner: false,
      shareVisibility: 'unlisted',
      shareLoading: false,
      publishing: false,
      publishConfirmOpen: false,
      copied: false,
      shareNotice: '',
      sourceNotice: '',
      createdAt: null,
      translationChecked: false,
      translationLanguage: '',
      translationLoading: false,
      translationVisible: false,
      translations: {},
      translationError: '',
    };
  },
  computed: {
    embedded() {
      return String(this.$route.query.embedded || '') === '1';
    },
    showBackLink() {
      // Only offer a return when the visitor arrived from inside the site
      // through SPA navigation. A fresh tab or direct load has no in-app
      // origin to return to, so no back control is shown.
      return Boolean(getViewOriginRoute());
    },
    originLabel() {
      const route = getViewOriginRoute() || (this.session && this.session.origin && this.session.origin.route);
      const path = String(route || '').split(/[?#]/)[0];
      return route ? (ROUTE_LABELS[path] || 'the previous page') : 'Home';
    },
    sourceCount() {
      const ids = new Set();
      for (const section of this.view.sections || []) {
        for (const block of section.blocks || []) {
          if (block.kind === 'source' && block.source_id) ids.add(block.source_id);
        }
      }
      return ids.size;
    },
    viewSources() {
      const seen = new Set();
      const sources = [];
      for (const section of this.view.sections || []) {
        for (const block of section.blocks || []) {
          if (block.kind !== 'source' || !block.source_id || seen.has(block.source_id)) continue;
          const source = this.sourceFor(block.source_id);
          if (!source) continue;
          seen.add(block.source_id);
          sources.push(source);
        }
      }
      return sources;
    },
    displayQuestion() {
      const saved = String(this.view.question || '').trim();
      if (saved) return saved;
      if (this.shareId) return '';
      const turns = this.session && Array.isArray(this.session.turns) ? this.session.turns : [];
      const latestUserTurn = [...turns].reverse().find((turn) => turn.role === 'user');
      return latestUserTurn ? String(latestUserTurn.text || '').trim() : '';
    },
    sharing() {
      return viewSharingState(this);
    },
    formattedCreatedAt() {
      if (!this.createdAt) return '';
      const date = new Date(this.createdAt);
      if (Number.isNaN(date.getTime())) return '';
      return new Intl.DateTimeFormat('en-GB', {
        day: 'numeric',
        month: 'long',
        year: 'numeric',
      }).format(date);
    },
    createdAtIso() {
      if (!this.createdAt) return '';
      const date = new Date(this.createdAt);
      return Number.isNaN(date.getTime()) ? '' : date.toISOString();
    },
    translationAvailable() {
      return this.translationChecked && this.translationLanguage !== 'en';
    },
    hasTranslations() {
      return Object.keys(this.translations).length > 0;
    },
    translationLang() {
      const source = /^[a-z]{2,3}(?:-[A-Za-z]+)?$/.test(this.translationLanguage)
        ? this.translationLanguage
        : 'und';
      return `en-x-mtfrom-${source}`;
    },
  },
  created() {
    this._routeLoadToken = 0;
    this._translationToken = 0;
  },
  async mounted() {
    await this.loadRouteView();
  },
  watch: {
    '$route.fullPath'() {
      const nextShareId = String(this.$route.params.shareId || '');
      if (nextShareId === this.shareId) return;
      this.loadRouteView();
    },
  },
  methods: {
    resetRouteView() {
      this.view = {
        schema_version: 1,
        question: '',
        lens: '',
        title: 'Composed view',
        dek: '',
        sections: [],
      };
      this.sourcesById = new Map();
      this.currentSourcesById = new Map();
      this.viewError = false;
      this.fatalError = '';
      this.sourcesLoading = true;
      this.shareOwner = false;
      this.shareVisibility = 'unlisted';
      this.shareLoading = false;
      this.publishing = false;
      this.publishConfirmOpen = false;
      this.copied = false;
      this.shareNotice = '';
      this.sourceNotice = '';
      this.createdAt = null;
      this.translationChecked = false;
      this.translationLanguage = '';
      this.translationLoading = false;
      this.translationVisible = false;
      this.translations = {};
      this.translationError = '';
      this._translationToken += 1;
    },
    async loadRouteView() {
      const token = ++this._routeLoadToken;
      const requestedShareId = String(this.$route.params.shareId || '');
      this.resetRouteView();
      this.session = loadAskSession();
      this.shareId = requestedShareId;

      if (requestedShareId) {
        await this.restoreSharedView(token, requestedShareId);
        return;
      }

      const currentView = this.session?.currentView;
      if (!currentView) {
        this.goBack(true);
        return;
      }
      this.view = currentView;
      this.createdAt = this.session?.currentShare?.created_at || Date.now();
      const loaded = await this.loadSources();
      if (token !== this._routeLoadToken) return;
      if (!loaded) {
        this.sourcesLoading = false;
        this.fatalError = 'Henry’s original site material is unavailable. Please return and try again.';
        return;
      }
      const validationError = validateViewState(currentView, this.sourcesById);
      if (validationError) {
        this.sourcesLoading = false;
        this.fatalError = 'Some of the original material has changed, so this saved View cannot be opened completely.';
        return;
      }
      this.shareOwner = true;
      this.finishViewLoad();
      await this.ensurePermanentLink(token);
    },
    finishViewLoad() {
      this.sourcesLoading = false;
      this.revision = 1;
      document.title = `${this.view.title} - H.W.`;
      const pendingScroll = consumePendingViewReturnScroll();
      if (pendingScroll !== null) {
        // Returning through the "Back to View" control: land where the visitor
        // left off once the sources have loaded, instead of the usual top.
        this.$nextTick(() => window.scrollTo({ top: pendingScroll, left: 0, behavior: 'auto' }));
      } else {
        window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
      }
      logEvent('view_open', {
        n_sections: this.view.sections ? this.view.sections.length : 0,
        n_sources: this.view.sections ? this.view.sections.reduce((sum, section) => sum + (section.blocks || []).filter((b) => b.kind === 'source').length, 0) : 0,
      });
      this.$nextTick(() => {
        this.refreshScrollReveal();
        this.$refs.viewTitle?.focus({ preventScroll: true });
      });
      if (this.shareId) this.detectViewLanguage();
    },
    async restoreSharedView(token = this._routeLoadToken, requestedShareId = this.shareId) {
      try {
        const snapshot = await getSharedView(requestedShareId);
        if (token !== this._routeLoadToken || requestedShareId !== this.shareId) return;
        this.view = snapshot.view;
        this.sourcesById = new Map((snapshot.sources || []).map((source) => [source.source_id, source]));
        await this.loadCurrentSources();
        if (token !== this._routeLoadToken || requestedShareId !== this.shareId) return;
        for (const section of this.view.sections || []) {
          for (const block of section.blocks || []) {
            if (block.kind !== 'bridge') continue;
            for (const sourceId of block.source_ids || []) {
              if (!this.sourcesById.has(sourceId)) {
                this.sourcesById.set(sourceId, { source_id: sourceId, parts: [], presentations: [] });
              }
            }
          }
        }
        this.shareOwner = snapshot.owner === true;
        this.shareVisibility = snapshot.visibility || 'unlisted';
        this.createdAt = snapshot.created_at || null;
        const validationError = validateViewState(this.view, this.sourcesById);
        if (validationError) throw new Error(validationError);
        this.finishViewLoad();
      } catch (error) {
        if (token !== this._routeLoadToken || requestedShareId !== this.shareId) return;
        console.error('shared view restore failed:', error);
        this.sourcesLoading = false;
        this.fatalError = 'This saved View is unavailable or incomplete.';
      }
    },
    async ensurePermanentLink(token = this._routeLoadToken) {
      if (!this.shareOwner || this.shareLoading) return;
      this.shareNotice = '';
      const existing = this.session?.currentShare;
      if (existing?.id) {
        if (token !== this._routeLoadToken) return;
        this.shareId = existing.id;
        this.shareOwner = true;
        this.shareVisibility = existing.visibility || 'unlisted';
        this.createdAt = existing.created_at || null;
        await this.$router.replace(`/view/${existing.id}`).catch(() => {});
        if (token === this._routeLoadToken) document.title = `${this.view.title} - H.W.`;
        if (token === this._routeLoadToken) this.detectViewLanguage();
        return;
      }
      this.shareLoading = true;
      try {
        const share = await createSharedView(this.view, await this.snapshotSources());
        if (token !== this._routeLoadToken) return;
        this.shareId = share.id;
        this.shareOwner = true;
        this.shareVisibility = share.visibility;
        this.createdAt = share.created_at || Date.now();
        this.session = setAskShare(this.session, share);
        await this.$router.replace(`/view/${share.id}`).catch(() => {});
        if (token === this._routeLoadToken) document.title = `${this.view.title} - H.W.`;
        if (token === this._routeLoadToken) this.detectViewLanguage();
      } catch (error) {
        if (token !== this._routeLoadToken) return;
        console.error('permanent view save failed:', error);
        this.shareNotice = 'The shareable link is temporarily unavailable. Please try again.';
      } finally {
        if (token === this._routeLoadToken) this.shareLoading = false;
      }
    },
    async translationRequest(method, id, token) {
      for (let attempt = 0; attempt < 8; attempt += 1) {
        const result = method === 'POST'
          ? await translateViewToEnglish(id)
          : await getViewTranslationStatus(id);
        if (token !== this._translationToken || id !== this.shareId) return null;
        if (result.status !== 'preparing') return result;
        await new Promise(resolve => window.setTimeout(resolve, 900 + attempt * 120));
      }
      throw new Error('translation_preparing');
    },
    applyTranslationResult(result) {
      if (!result) return;
      this.translationLanguage = String(result.sourceLanguage || 'und');
      this.translationChecked = true;
      if (result.translations && typeof result.translations === 'object') this.translations = result.translations;
    },
    async detectViewLanguage() {
      const id = this.shareId;
      if (!id || this.translationChecked || this.translationLoading) return;
      const token = ++this._translationToken;
      this.translationLoading = true;
      try {
        const result = await this.translationRequest('GET', id, token);
        if (result) this.applyTranslationResult(result);
      } catch (error) {
        if (token !== this._translationToken || id !== this.shareId) return;
        console.warn('View language detection unavailable:', error);
        // Keep the existing View unchanged when the provider cannot identify
        // its language. A failed control would offer no useful next action.
        this.translationLanguage = '';
        this.translationChecked = false;
      } finally {
        if (token === this._translationToken && id === this.shareId) this.translationLoading = false;
      }
    },
    async toggleTranslation() {
      if (this.translationVisible) {
        this.translationVisible = false;
        return;
      }
      if (this.hasTranslations) {
        this.translationVisible = true;
        return;
      }
      const id = this.shareId;
      if (!id || this.translationLoading) return;
      const token = ++this._translationToken;
      this.translationLoading = true;
      this.translationError = '';
      try {
        const result = await this.translationRequest('POST', id, token);
        if (!result) return;
        this.applyTranslationResult(result);
        if (this.translationLanguage === 'en') return;
        if (!this.hasTranslations) throw new Error('translation_unavailable');
        this.translationVisible = true;
      } catch (error) {
        if (token !== this._translationToken || id !== this.shareId) return;
        console.warn('View translation unavailable:', error);
        this.translationError = error?.message === 'translation_preparing'
          ? 'The English translation is still preparing. Try again in a moment.'
          : 'Translation is temporarily unavailable. Please try again.';
      } finally {
        if (token === this._translationToken && id === this.shareId) this.translationLoading = false;
      }
    },
    translationFor(id) {
      const value = this.translations?.[id];
      return typeof value === 'string' ? value : String(value?.text || '');
    },
    async snapshotSources() {
      await this.$nextTick();
      const htmlById = new Map();
      for (const element of this.$el.querySelectorAll('.view-block[data-source-id]')) {
        const sourceId = element.dataset.sourceId;
        const source = this.sourceFor(sourceId);
        if (!source?.rich) continue;
        const content = element.querySelector('.origin-content');
        if (!content) continue;
        const clone = content.cloneNode(true);
        for (const node of clone.querySelectorAll('[src], [poster]')) {
          for (const attribute of ['src', 'poster']) {
            const value = node.getAttribute(attribute);
            if (!value) continue;
            try {
              node.setAttribute(attribute, new URL(value, 'https://www.henryw.me').toString());
            } catch {
              // Keep the original value if it cannot be resolved.
            }
          }
        }
        for (const node of clone.querySelectorAll('button, input, select, textarea')) {
          node.setAttribute('disabled', 'disabled');
          node.setAttribute('aria-disabled', 'true');
        }
        htmlById.set(sourceId, clone.innerHTML);
      }
      const sourceIds = new Set();
      for (const section of this.view.sections || []) {
        for (const block of section.blocks || []) {
          if (block.kind === 'source' && block.source_id) sourceIds.add(block.source_id);
          if (block.kind === 'bridge') {
            for (const sourceId of block.source_ids || []) sourceIds.add(sourceId);
          }
        }
      }
      return Promise.all([...sourceIds].map((sourceId) => this.sourceFor(sourceId)).filter(Boolean).map(async (source) => {
        const snapshot = JSON.parse(JSON.stringify(source));
        snapshot.source_fingerprint = await sourceFingerprint(source);
        snapshot.snapshot_html = htmlById.get(source.source_id) || '';
        snapshot.media = (snapshot.media || []).map((media) => {
          const next = { ...media };
          for (const field of ['src', 'fullSrc']) {
            if (!next[field]) continue;
            try { next[field] = new URL(next[field], 'https://www.henryw.me').toString(); } catch { /* keep source */ }
          }
          return next;
        });
        return snapshot;
      }));
    },
    async copyShareLink() {
      if (!this.shareId) return;
      const url = `${window.location.origin}${window.location.pathname}#/view/${this.shareId}`;
      try {
        await navigator.clipboard.writeText(url);
      } catch {
        const input = document.createElement('textarea');
        input.value = url;
        document.body.appendChild(input);
        input.select();
        document.execCommand('copy');
        input.remove();
      }
      this.copied = true;
      window.setTimeout(() => { this.copied = false; }, 1800);
    },
    async publishView() {
      if (!this.sharing.canPublish) return;
      this.publishing = true;
      this.shareNotice = '';
      try {
        const result = await publishSharedView(this.shareId);
        this.shareVisibility = 'public';
        this.publishConfirmOpen = false;
        this.session = setAskShare(this.session, { id: this.shareId, visibility: 'public' });
        this.shareNotice = result.featured === false
          ? 'Shared publicly. A closely related View already appears in the main collection, and this View remains available through search.'
          : 'Shared publicly. Visitors can now find this View in Shared Views.';
      } catch (error) {
        console.error('view publish failed:', error);
        this.shareNotice = 'This View could not be shared publicly. Please try again.';
      } finally {
        this.publishing = false;
      }
    },
    openPublishConfirmation() {
      if (!this.sharing.canPublish) return;
      this.shareNotice = '';
      this.publishConfirmOpen = true;
      this.$nextTick(() => {
        this.$refs.publishConfirm?.focus({ preventScroll: true });
      });
    },
    closePublishConfirmation() {
      if (this.publishing) return;
      this.publishConfirmOpen = false;
    },
    citationTitle(source) {
      const title = String(source?.title || source?.page || 'Original source');
      const organisation = String(source?.entity?.organisation || '').trim();
      return organisation && !title.includes(organisation) ? `${title} · ${organisation}` : title;
    },
    blockClass(block) {
      if (block && block.kind === 'source') {
        return [`prominence-${block.prominence || 'standard'}`, `presentation-${block.presentation || 'excerpt'}`];
      }
      return ['prominence-standard', 'presentation-bridge'];
    },
    async loadSources() {
      try {
        const map = await this.fetchCurrentSourceMap();
        this.sourcesById = map;
        this.currentSourcesById = map;
        return true;
      } catch (err) {
        console.error('view index load failed:', err);
        return false;
      }
    },
    async loadCurrentSources() {
      try {
        this.currentSourcesById = await this.fetchCurrentSourceMap();
      } catch (error) {
        console.warn('current source comparison unavailable:', error);
        this.currentSourcesById = new Map();
      }
    },
    async fetchCurrentSourceMap() {
      const res = await fetch('/assets/view-index.json', { cache: 'no-cache' });
      if (!res.ok) throw new Error(`view-index.json ${res.status}`);
      const data = await res.json();
      const map = new Map(createViewCatalog(data).map((source) => [
        source.source_id, { ...source, title: sourceDisplayTitle(source) },
      ]));
      return map;
    },
    currentSourceFor(id) {
      return this.currentSourcesById.get(id) || null;
    },
    sourceFor(sourceId) {
      if (this.sourcesById.has(sourceId)) return this.sourcesById.get(sourceId);
      return null;
    },
    markSourceError() {
      this.viewError = true;
    },
    openSource(source) {
      if (!source || !source.route) return;
      const target = viewSourceTarget(source);
      if (!target) return;
      logEvent('view_source_open', {
        source_id: source.source_id || null,
        route: target.path,
        anchor: source.anchor || null,
      });
      if (!this.$router.resolve(target).matched.length) {
        this.sourceNotice = 'The original page has since been removed from Henry’s site. This View keeps the source as it appeared when it was created.';
        return;
      }
      target.state = {
        viewReturnRoute: this.$route.fullPath,
        viewReturnScrollY: window.scrollY,
      };
      this.$router.push(target).catch(() => {});
    },
    sourcePageLabel,
    goBack(replace = false) {
      const fallback = this.session && this.session.origin ? this.session.origin.route : '/home';
      if (replace) {
        this.$router.replace(fallback).catch(() => {});
      } else if (window.history.length > 1) {
        this.$router.back();
      } else {
        this.$router.replace(fallback).catch(() => {});
      }
    },
  },
};
