.cs-stage :deep(.text-title) { font-family: "PT Serif", Georgia, serif; font-weight: 700; color: #2f2f2f; margin: 0 0 0.9rem; line-height: 1.18; font-size: clamp(1.6rem, 3.4vw, 2.3rem); }
.cs-stage :deep(.text-body) { color: #767676; line-height: 1.62; max-width: 46ch; margin: 0 auto; font-size: clamp(0.98rem, 1.4vw, 1.12rem); }
