.cs-stage :deep(.fx-underline) { background-image: linear-gradient(currentColor, currentColor); background-position: 0 100%; background-repeat: no-repeat; background-size: 0% 2px; transition: background-size 0.55s ease; }
.cs-stage :deep(.fx-highlight) { background-image: linear-gradient(rgba(85, 102, 166, 0.28), rgba(85, 102, 166, 0.28)); background-position: 0 86%; background-repeat: no-repeat; background-size: 0% 0.92em; transition: background-size 0.55s ease; border-radius: 2px; }
.cs-stage.fx-on :deep(.fx-underline) { background-size: 100% 2px; }
